#!/usr/bin/env pwsh
# Reset the module to a clean state (Windows counterpart of scripts/reset.sh).
$ErrorActionPreference = "Stop"
Set-Location (Join-Path $PSScriptRoot "..")

if (Test-Path "state") { Remove-Item "state" -Recurse -Force }
# Generated by `task plan`; the committed SDD-ORD-004.patch is a deliverable and stays.
Remove-Item "artifacts\diffs\*.plan.json" -ErrorAction SilentlyContinue
# artifacts\records\llm-calls.jsonl and artifacts\logs are kept: they are the recorded
# evidence for this submission. A new `task plan` appends to the call record.

if (Test-Path "sample-project\snapshots\after\src\orderflow") {
  Copy-Item "sample-project\snapshots\after\src\orderflow\*.py" "sample-project\src\orderflow\" -Force
}

Write-Host "state removed; sample-project restored to the post-change snapshot"
